"""Plan solver stress: timing + exhaustive verification (dev only)."""
import importlib.util, json, random, sys, time
sys.path.insert(0, '/workspace/dev')

spec = importlib.util.spec_from_file_location('m', '/workspace/submission/main.py')
m = importlib.util.module_from_spec(spec); spec.loader.exec_module(m)


def brute(flows, caps, bens, pinned):
    """Exhaustive feasibility-only enumeration; returns (best_benefit, min_count)."""
    n = len(flows)
    nodes = sorted(caps)
    nidx = {nd: i for i, nd in enumerate(nodes)}
    use = [tuple(nidx[nd] for nd in f['path']) for f in flows]
    cap = [caps[nd] for nd in nodes]
    used = [0] * len(nodes)
    for p in pinned:
        for j in use[p]:
            used[j] += 1
    for j in range(len(nodes)):
        if used[j] > cap[j]:
            return None
    free = [i for i in range(n) if i not in set(pinned)]
    best = [sum(bens[p] for p in pinned), len(pinned)]

    def rec(k, ben, cnt):
        if ben > best[0] or (ben == best[0] and cnt < best[1]):
            best[0], best[1] = ben, cnt
        if k == len(free):
            return
        i = free[k]
        rec(k + 1, ben, cnt)
        u = use[i]
        ok = True
        for j in u:
            if used[j] + 1 > cap[j]:
                ok = False
                break
        if ok:
            for j in u:
                used[j] += 1
            rec(k + 1, ben + bens[i], cnt + 1)
            for j in u:
                used[j] -= 1
    rec(0, best[0], best[1])
    return best


def make_req(rng, n, nnodes, pathlen, capmode, benmode):
    nodes = ['n%d' % i for i in range(nnodes)]
    caps = {}
    for nd in nodes:
        if capmode == 'tight':
            caps[nd] = rng.choice([0, 1, 1, 2, 2, 3])
        elif capmode == 'loose':
            caps[nd] = rng.choice([3, 5, 10, 512])
        else:
            caps[nd] = rng.choice([0, 1, 2, 3, 5, 20])
    flows = []
    for i in range(n):
        L = rng.randint(2, min(pathlen, nnodes))
        path = rng.sample(nodes, L)
        H = 8
        kinds = 'K' * (H - 5) + 'DQTKZ'[:0]  # build valid kinds below
        kinds = list('K' * (H - 4) + 'QTKZ'[:0])
        # simple valid kinds: H-3 K, one D, one Q, one T  (4+1<H holds for H>=8)
        kinds = ['K'] * H
        kinds[0] = 'D'; kinds[1] = 'Q'; kinds[2] = 'T'
        kinds = ''.join(kinds)
        tmpl = bytes([0xaa, 0, 0xff] + [0] * (H - 3))
        flows.append({'id': 'f%d' % i, 'path': path, 'template': tmpl.hex(), 'kinds': kinds})
    # offers: one run per flow with eligible header -> benefit = ben * per
    per = [(len(bytes.fromhex(f['template'])) - 4 - f['kinds'].count('D')) * len(f['path'])
           for f in flows]
    offers = {}
    bens = []
    for i, f in enumerate(flows):
        H = len(bytes.fromhex(f['template']))
        kinds = f['kinds']
        hdr = bytearray(H)
        for j, ch in enumerate(kinds):
            if ch == 'K':
                hdr[j] = bytes.fromhex(f['template'])[j]
            elif ch == 'Q':
                hdr[j] = 3
            elif ch == 'T':
                hdr[j] = 200
        if benmode == 'equal':
            cnt = 1000
        elif benmode == 'small':
            cnt = rng.randint(1, 20)
        elif benmode == 'pow2':
            cnt = 1 << rng.randint(0, 10)
        else:
            cnt = rng.randint(1, 10 ** 6)
        offers[f['id']] = [{'header': hdr.hex(), 'count': cnt}]
        bens.append(cnt * per[i])
    pinned = [f['id'] for f in flows if rng.random() < 0.1]
    pinidx = [i for i, f in enumerate(flows) if f['id'] in pinned]
    req = {'mode': 'plan', 'capacities': caps, 'flows': flows, 'warmup': 0,
           'pinned': pinned, 'offers': offers}
    return req, bens, pinidx


def main():
    seed = int(sys.argv[1]); iters = int(sys.argv[2]); n = int(sys.argv[3])
    capmode = sys.argv[4]; benmode = sys.argv[5]
    verify = len(sys.argv) > 6 and sys.argv[6] == 'verify'
    rng = random.Random(seed)
    worst = 0.0; bad = 0
    for it in range(iters):
        nnodes = rng.choice([4, 8, 16, 32, 64])
        pathlen = rng.randint(2, 9)
        req, bens, pinidx = make_req(rng, n, min(nnodes, 64), pathlen, capmode, benmode)
        t0 = time.time()
        got = m.handle(json.loads(json.dumps(req)))
        dt = time.time() - t0
        worst = max(worst, dt)
        if dt > 3.0:
            print('SLOW %.2fs it=%d req=%s' % (dt, it, json.dumps(req)[:400]))
        if 'error' in got:
            print('ERROR response', json.dumps(req)[:600]); bad += 1; continue
        if verify:
            t1 = time.time()
            exp = brute(req['flows'], req['capacities'], bens, pinidx)
            if exp is None:
                if got != {'infeasible': True}:
                    print('MISMATCH infeasible', got, json.dumps(req)[:400]); bad += 1
            else:
                if got['saved'] != exp[0] or len(got['selected']) != exp[1]:
                    print('MISMATCH it=%d got saved=%d cnt=%d exp=%s' % (it, got['saved'], len(got['selected']), exp))
                    print(json.dumps(req)[:1200])
                    bad += 1
            if time.time() - t1 > 120:
                print('brute slow')
        else:
            # structural checks only: feasibility + pinned present
            fmap = {f['id']: f for f in req['flows']}
            sel = got['selected']
            if sorted(sel) != sel or len(set(sel)) != len(sel):
                print('bad selected list', sel); bad += 1
            for nd, c in req['capacities'].items():
                if sum(1 for s in sel if nd in fmap[s]['path']) > c:
                    print('infeasible selection', nd, sel); bad += 1
            for p in req['pinned']:
                if p not in sel:
                    print('missing pinned'); bad += 1
            bmap = dict(zip([f['id'] for f in req['flows']], bens))
            if sum(bmap[s] for s in sel) != got['saved']:
                print('saved mismatch'); bad += 1
    print('done iters=%d n=%d cap=%s ben=%s bad=%d worst=%.3fs' % (iters, n, capmode, benmode, bad, worst))


main()
